import{z as A,x as n,o as r,c as d,q as t,j as o,D as e,d as B,s as i,S as s,b as E}from"./chunks/framework.C8m1ZpeB.js";const C=JSON.parse('{"title":"黑边","description":"","frontmatter":{"title":"黑边","date":"2026-09-08T00:00:00.000Z","section":"litho"},"headers":[],"relativePath":"litho/black-border.md","filePath":"litho/black-border.md","lastUpdated":1791413859000}'),p={name:"litho/black-border.md"};function h(m,a,D,c,b,f){const l=n("Mermaid");return r(),d("div",null,[a[2]||(a[2]=t('<h1 id="黑边" tabindex="-1">黑边 <a class="header-anchor" href="#黑边" aria-label="Permalink to &quot;黑边&quot;">​</a></h1><div class="epigraph"><p>EUV 掩模在场外仍是镜子。相邻曝光场会把这块反射印进芯片边缘。黑边把场周多层去掉，让边缘真正变黑。</p><footer>—— 对照 ASML / 掩模厂对 EUV black border 的公开方案</footer></div><p><a href="/litho/ruthenium-capping">上一课</a>把图形区多层用钌帽保护起来。缺口是场与场之间：扫描机按场步进，照明和投影的光晕会打到掩模上图形区以外的多层，反射式几何把它当成合法物面，邻场边缘出现「闪光」或 CD 异常。本课钉黑边（black border）。掩模三维导致的最佳焦面偏移，留给<a href="/litho/mask-3d-best-focus-shift">下一课</a>。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>DUV 透射版场外是铬挡光，天然较黑。EUV 空白是高反多层，场外若不处理，就是一块亮镜。环形场照明有限，仍有杂散和扫描过扫描（overscan）打到边框。邻场在硅片上拼接时，这块反射造成边缘剂量和套刻干扰。吸收体若只做到图形区，边框多层仍亮。</p><p><span class="marginnote">直觉类比：EUV 掩模本质上是一面镜子——图像不是透过掩模，而是从掩模表面反射进镜头。图形区以外若不处理，就是一块擦得锃亮的镜子，扫描光斑的边缘和杂散光都会从那里原路弹回晶圆。</span></p><p>缺口是把「场外必须不反光」做成掩模结构，而不是靠叶片完全挡死——<a href="/litho/reticle-masking-blades">遮挡叶片</a> 有衍射和定位公差，EUV 仍需要版上黑边作为合同。</p><p><span class="marginnote">黑边是蚀掉或破坏多层反射，不是涂一圈黑漆。13.5 nm 没有可用的厚吸收涂料当边框。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>公开做法：在场周把 Mo/Si 堆蚀到低反状态（去掉足够周期或蚀到基板），形成指定宽度的暗框。宽度要覆盖照明过扫描与对准标记布局，又不能吃掉有效场。蚀深和侧壁影响边框本身的三维散射，可能在场边缘加一条 flare。叶片仍用于曝光场定义，与黑边分层：叶片挡大部分，黑边收残余。</p><p>检验：边框反射率、宽度、与图形的套准。修复黑边缺陷等于在最边缘动多层，风险高，设计上往往禁止关键图形贴边过近。</p><p><span class="marginnote">为什么重要：黑边缺陷几乎没法修——修复等于在掩模最边缘动多层结构，稍一失手整块报废。所以版图规则常禁止关键图形贴场边太近：黑边宽度是硬边距预算，不是美观问题。</span></p><h3 id="叶片衍射不是黑边的替代" tabindex="-1">叶片衍射不是黑边的替代 <a class="header-anchor" href="#叶片衍射不是黑边的替代" aria-label="Permalink to &quot;叶片衍射不是黑边的替代&quot;">​</a></h3><p>遮挡叶片有刃口衍射和定位公差，EUV 短波把衍射角铺开。只靠叶片、场外仍是高反多层，过扫描或杂散会在邻场边缘留下剂量尾巴。黑边把物面本身变黑，与叶片串级。宽度规格来自过扫描预算，不是美学边框。</p>',14)),(r(),o(s,null,{default:e(()=>[i(l,{id:"mermaid-40",class:"mermaid",graph:"flowchart%20TD%0A%20%20ML%5B%22%E5%9C%BA%E5%A4%96%E5%A4%9A%E5%B1%82%E4%BB%8D%E9%AB%98%E5%8F%8D%22%5D%20--%3E%20BB%5B%22%E8%9A%80%E5%A4%9A%E5%B1%82%E5%81%9A%E9%BB%91%E8%BE%B9%22%5D%0A%20%20BL%5B%22%E5%8F%B6%E7%89%87%E8%BF%87%E6%89%AB%E6%8F%8F%E5%85%AC%E5%B7%AE%22%5D%20--%3E%20BB%0A%20%20BB%20--%3E%20EDGE%5B%22%E9%82%BB%E5%9C%BA%E8%BE%B9%E7%BC%98%E5%89%82%E9%87%8F%E5%B9%B2%E5%87%80%22%5D%0A%20%20BB%20--%3E%20SC%5B%22%E8%BE%B9%E6%A1%86%E4%B8%89%E7%BB%B4%E6%95%A3%E5%B0%84%22%5D%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[B(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=E("h2",{id:"机制",tabindex:"-1"},[B("机制 "),E("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=E("p",null,"多层少若干周期，布拉格峰值塌掉，\\(R\\) 降到百分之几。残余反射仍随角变，斜入射下边框不是理想零。边框台阶是一个深的三维物，衍射会进投影光瞳，表现为场边缘的局部底座——与图形区 flare 不同源。步进重复时，上一场的黑边位置必须与本场叶片对齐，否则亮缝闪一下。",-1)),a[5]||(a[5]=E("p",null,[E("span",{class:"marginnote"},"数字实例：几十对 Mo/Si 叠起来能把反射率做到约七成；黑边把周期蚀掉足够多，布拉格峰塌掉，反射率掉到百分之几。残余虽小，但场边缘的剂量尾巴是可量测的，这就是宽度规格要从过扫描预算里算的原因。")],-1)),(r(),o(s,null,{default:e(()=>[i(l,{id:"mermaid-50",class:"mermaid",graph:"flowchart%20TD%0A%20%20DUV%5B%22DUV%20%E9%80%8F%E5%B0%84%E6%8E%A9%E6%A8%A1%22%5D%20--%3E%20CR%5B%22%E5%9C%BA%E5%A4%96%E6%98%AF%E9%93%AC%EF%BC%8C%E5%A4%A9%E7%84%B6%E6%8C%A1%E5%85%89%22%5D%0A%20%20CR%20--%3E%20DOK%5B%22%E5%9C%BA%E5%A4%96%E8%BF%91%E4%BC%BC%E9%9B%B6%E5%8F%8D%E5%B0%84%22%5D%0A%20%20EUV%5B%22EUV%20%E5%8F%8D%E5%B0%84%E6%8E%A9%E6%A8%A1%22%5D%20--%3E%20MLT%5B%22%E5%9C%BA%E5%A4%96%E6%98%AF%20Mo%2FSi%20%E9%AB%98%E5%8F%8D%E5%A4%9A%E5%B1%82%22%5D%0A%20%20MLT%20--%3E%20PROB%5B%22%E9%82%BB%E5%9C%BA%E8%BE%B9%E7%BC%98%E8%A2%AB%E5%8F%8D%E5%B0%84%E7%85%A7%E6%98%8E%E6%B1%A1%E6%9F%93%22%5D%0A%20%20PROB%20--%3E%20FIX%5B%22%E8%A7%A3%E6%B3%95%EF%BC%9A%E7%89%88%E4%B8%8A%E9%BB%91%E8%BE%B9%E4%B8%8E%E5%8F%B6%E7%89%87%E4%B8%B2%E7%BA%A7%22%5D%0A%20%20FIX%20--%3E%20EDGE%5B%22%E8%BE%B9%E6%A1%86%E6%95%A3%E5%B0%84%E4%B8%8E%E5%AE%BD%E5%BA%A6%E9%A2%84%E7%AE%97%22%5D%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[B(" Loading... ",-1)])]),_:1})),a[6]||(a[6]=t('<p><span class="marginnote">High-NA 半场让「边缘」占场的比例上升，黑边和叶片的相对重要性增加。机制不变，公差更紧。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不把吸收体 3D 的最佳焦点公式写完，下一课才把图形区 M3D 的焦移钉死。不重写 DUV 铬边框。黑边宽度吃有效场，与环形场弧长是同一张版图边距预算。出处：ASML EUV black border；掩模厂公开工艺叙述；叶片课。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>场外多层必须被做成黑边，否则邻场边缘被反射照明污染。</li><li>叶片与黑边分工：粗挡与版上合同。</li><li>下一课：图形区三维电磁如何把最佳焦面拉开。</li><li>出处：ASML；EUV mask black border 公开材料。</li></ul>',5))])}const _=A(p,[["render",h]]);export{C as __pageData,_ as default};
